import os
import torch


class Config:
    """
    Configuration class for the MRI segmentation project.
    Contains paths, model hyperparameters, training settings, and hardware config.
    """

    # =========================================================================
    # Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    SUBMISSION_DIR = "./submission"

    # Metadata files generated by the metadata script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Sample submission file provided by competition
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Directory for caching intermediate data (e.g., preprocessed arrays)
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_1")

    # =========================================================================
    # Data & Preprocessing
    # =========================================================================
    IMAGE_SIZE = 320  # Input resolution (320x320)
    IN_CHANNELS = 3  # 2.5D input: (slice-1, slice, slice+1)
    NUM_CLASSES = 3  # Large Bowel, Small Bowel, Stomach
    CLASSES = ["large_bowel", "small_bowel", "stomach"]

    # Physical properties
    SLICE_DEPTH_MM = 3.0  # Thickness in superior-inferior direction

    # =========================================================================
    # Model Architecture
    # =========================================================================
    BACKBONE = "resnet18"  # Encoder backbone
    PRETRAINED = True  # Use ImageNet weights

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    BATCH_SIZE = 64
    EPOCHS = 12
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-6

    # Optimizer & Scheduler
    OPTIMIZER = "Adam"
    SCHEDULER = "CosineAnnealingLR"
    MIN_LR = 1e-6

    # Loss weights (0.4 Dice, 0.6 Hausdorff approximation via BCE/Focal)
    # Note: Hausdorff is hard to optimize directly, usually BCE+Dice is used.
    # We will use equal weighting or tune based on validation.
    LOSS_WEIGHT_BCE = 0.5
    LOSS_WEIGHT_DICE = 0.5

    # =========================================================================
    # Compute & Reproducibility
    # =========================================================================
    SEED = 42
    NUM_WORKERS = 4  # Number of dataloader workers
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # =========================================================================
    # Debugging / Development
    # =========================================================================
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SAMPLE_SIZE = 100  # Number of samples for debugging

    @classmethod
    def setup(cls, debug=None, training=True):
        """
        Setup method to initialize directories and override settings if needed.

        Args:
            debug (bool, optional): Override debug mode.
            training (bool): Whether the setup is for training (creates working dirs).
        """
        if debug is not None:
            cls.DEBUG = debug

        if cls.DEBUG:
            cls.EPOCHS = 2
            cls.BATCH_SIZE = 16
            print(f"DEBUG MODE ENABLED: Epochs={cls.EPOCHS}, Batch={cls.BATCH_SIZE}")

        if training:
            os.makedirs(cls.WORKING_DIR, exist_ok=True)
            os.makedirs(cls.CACHE_DIR, exist_ok=True)
            os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def to_dict(cls):
        """Returns configuration as a dictionary."""
        return {
            k: v
            for k, v in cls.__dict__.items()
            if not k.startswith("__") and not callable(v)
        }
